// SegmentedTabs (ds-metrics §17 — GlassSegmentedTabs .accentPill): 48pt track, radius 24 (no token), padding h 4 / v 2,
// gap 4; regular material under bg1Elevated at 96% light / 72% dark, 1pt el16 hairline at 8% / 12%, light-only shadow
// cardShadow × 0.35 r8 y2. Segments share the width equally, bodyStrong; the selected one is a 44pt accentPrimary
// capsule with onAccent text, the others el9; cross-fade with @motion.smooth (the DS slides the pill with a spring). Controlled:
//   {"type": "SegmentedTabs", "props": {"items": "=tabs", "selected": "=tab"}, "on": {"change": "tab = event.index"}}
// `change` fires only for a segment that is not already selected.
param items: list<string>
param selected: number = 0
event change(index: number)
let dark = env.colorScheme == "dark"

on.tap:
if i != selected {
  haptic("selection")
  emit change({index: i})
}
